class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        INF = float('inf')
        # dp[a][b] = min sum using a op1 uses and b op2 uses so far
        dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0

        for x in nums:
            # Build options: (resulting value, op1 used, op2 used)
            half = (x + 1) // 2
            opts = [(x, 0, 0), (half, 1, 0)]
            if x >= k:
                opts.append((x - k, 0, 1))
                opts.append(((x - k + 1) // 2, 1, 1))  # op2 then op1
            if half >= k:
                opts.append((half - k, 1, 1))          # op1 then op2

            new_dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
            for a in range(op1 + 1):
                row = dp[a]
                for b in range(op2 + 1):
                    cur = row[b]
                    if cur == INF:
                        continue
                    for val, u1, u2 in opts:
                        na = a + u1
                        nb = b + u2
                        if na <= op1 and nb <= op2:
                            cand = cur + val
                            if cand < new_dp[na][nb]:
                                new_dp[na][nb] = cand
            dp = new_dp

        return int(min(min(row) for row in dp))
