class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        INF = float('inf')
        # dp[a][b] = min sum with a op1 used and b op2 used so far
        dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0
        for x in nums:
            # options: (cost_a, cost_b, value)
            opts = []
            opts.append((0, 0, x))
            c = (x + 1) // 2
            opts.append((1, 0, c))
            if x >= k:
                opts.append((0, 1, x - k))
                # op2 then op1
                opts.append((1, 1, (x - k + 1) // 2))
            # op1 then op2
            if c >= k:
                opts.append((1, 1, c - k))
            # keep best per (da, db)
            best = {}
            for da, db, v in opts:
                if (da, db) not in best or v < best[(da, db)]:
                    best[(da, db)] = v
            ndp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
            for a in range(op1 + 1):
                for b in range(op2 + 1):
                    cur = dp[a][b]
                    if cur == INF:
                        continue
                    for (da, db), v in best.items():
                        na, nb = a + da, b + db
                        if na <= op1 and nb <= op2:
                            val = cur + v
                            if val < ndp[na][nb]:
                                ndp[na][nb] = val
            dp = ndp
        ans = INF
        for a in range(op1 + 1):
            for b in range(op2 + 1):
                if dp[a][b] < ans:
                    ans = dp[a][b]
        return int(ans)
